  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED created a controllable regime for studying light–matter interaction with superconducting artificial atoms and became a foundation for quantum circuits. Its conceptual reach and sustained experimental impact are prize-level.",
        "attribution": "Blais provided the key theoretical proposal; Wallraff and Schoelkopf led landmark experimental demonstrations and development. Girvin made important theoretical contributions, so a three-person limit necessarily leaves out substantial credit.",
        "maturity": "The platform has been independently developed and used across many laboratories for roughly two decades. Its fundamental physics is established even as fault-tolerant applications remain incomplete.",
        "uncertainties": [
          "The discovery is cumulative, and the boundary between the original circuit-QED concept and later platform development is difficult to draw."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Theoretical frameworks and experiments with trapped ions and ultracold atoms made quantum information processing and simulation concrete physical disciplines. The work opened new ways to control and study quantum many-body systems.",
        "attribution": "Cirac and Zoller established central theoretical ideas; Blatt demonstrated and advanced quantum logic with trapped ions. The broader development involved many groups, but these three represent theory and decisive experimental realization.",
        "maturity": "The underlying methods have been reproduced and extended for decades. Quantum computers remain limited in scale, but the foundational physics is mature.",
        "uncertainties": [
          "The proposed discovery spans multiple platforms and achievements, making a single sharply bounded prize contribution difficult to define."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur K. Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "BB84 and E91 showed that quantum principles can support communication tasks with security unavailable classically. This was a foundational advance in quantum information, with broad experimental and conceptual influence.",
        "attribution": "Bennett and Brassard introduced BB84; Ekert independently developed the entanglement-based E91 approach. Their distinct contributions are identifiable and jointly capture the key conceptual routes.",
        "maturity": "The protocols have been studied, tested, and implemented in varied settings over several decades. Practical systems have limitations, but the underlying results are established.",
        "uncertainties": [
          "Real-world security depends on device assumptions and implementation details, though this does not undermine the foundational protocols."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite the fragility of quantum states, and fault-tolerant codes supplied a route to scalable quantum computation. This is a major conceptual achievement.",
        "attribution": "Shor and Steane introduced seminal codes, while Kitaev developed influential topological codes and fault-tolerance ideas. The field has many essential contributors, but these names capture distinct foundational directions.",
        "maturity": "The theory is mature and experimental demonstrations have advanced substantially, although large-scale fault-tolerant computing has not yet been achieved.",
        "uncertainties": [
          "The credited discovery groups several related theoretical advances whose relative weight could be judged differently."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "Susumu Noda"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and band gaps created a powerful means to control the propagation and emission of light. The idea has shaped photonics and remains important across basic science and technology.",
        "attribution": "Yablonovitch and John independently established the central photonic-band-gap concepts; Noda made influential advances in photonic-crystal structures and devices. Their contributions are complementary.",
        "maturity": "The phenomena and design principles have been confirmed across materials and laboratories over several decades.",
        "uncertainties": [
          "The breadth of later applications makes it difficult to distinguish the original conceptual breakthrough from subsequent engineering achievements."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements that surpass standard quantum limits and has made quantum optics a practical tool for precision measurement. Its use in gravitational-wave detection demonstrates its foundational reach.",
        "attribution": "Caves developed key theory; Kimble advanced experimental squeezed-light methods; Mavalvala helped establish their use in gravitational-wave interferometry. The contribution is collective, and Roman Schnabel is also a significant contributor.",
        "maturity": "The physics is well established, and squeezed light has been deployed in major instruments, though performance continues to improve.",
        "uncertainties": [
          "It is challenging to assign credit across theory, laboratory development, and large collaborative applications."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Paul B. Corkum",
        "Maciej Lewenstein",
        "Kenneth J. Schafer"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision picture connected intense-field electron motion to high-harmonic generation and enabled attosecond science. It provided a clear physical framework with lasting experimental consequences.",
        "attribution": "Corkum formulated the influential three-step model, while Lewenstein and Schafer made major theoretical contributions to its quantum description. The nominee set reasonably represents the model and its theoretical development.",
        "maturity": "The framework has been tested and extended for decades and underpins a mature research area.",
        "uncertainties": [
          "The advance arose through closely related theory and experiment across several groups, complicating a clean division of credit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable neutral-atom arrays offer a flexible route to controlled many-body physics and quantum simulation. The approach has produced important demonstrations, but its ultimate scientific impact is still unfolding.",
        "attribution": "Browaeys and Lukin led prominent experimental programs; Saffman made central contributions to neutral-atom quantum computing and its enabling methods. Many other groups have also shaped the field.",
        "maturity": "The platform is advancing rapidly, but the pace of development and the durability of its distinct scientific impact remain to be judged.",
        "uncertainties": [
          "The field is comparatively recent, and it is not yet clear which results will prove foundational rather than platform-specific."
        ]
      }
    }
  ]
